appendix+=table(['Model','Joint points','Reliability','Metric term','Both fail \\%','Both valid \\%'],rows,'lrrrrr','New joint contest, with baseline 50 points plus reliability and metric terms. The last two columns describe contest mass, not independent sample counts.','tab:joint')
